  const handleRegisterAgent = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newAgentName) return;
    const generatedCode = newAgentName.toUpperCase().replace(/[^A-Z0-9]/g, '_').substring(0, 15) || `AGENT_${Date.now()}`;
    try {
      const res = await ApiService.registerAIAgent({
        name: newAgentName,
        code: generatedCode,
        category: newAgentCategory || 'Specialized Assistant',
        promptVersion: newAgentPromptVersion || 'v1.0-prod'
      });
      if (res.success) {
        setIsCreateAgentModalOpen(false);
        setNewAgentName('');
        setNewAgentCode('');
        setNewAgentCategory('');
        setNewAgentPromptVersion('v1.0-prod');
        setUserFormNotification(`AI Agent '${newAgentName}' registered successfully!`);
        const agents = await ApiService.getAIAgents();
        if (agents.success) setAiAgentsList(agents.data);
      } else {
        alert(`Failed to register agent: ${res.error}`);
      }
    } catch (err: any) {
      alert(`Error registering agent: ${err.message}`);
    }
  };

  const handleEditAgent = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingAgentItem || !editAgentName) return;
    try {
      const res = await ApiService.updateAIAgent(editingAgentItem.id, {
        name: editAgentName,
        category: editAgentCategory,
        promptVersion: editAgentPromptVersion
      });
      if (res.success) {
        setIsEditAgentModalOpen(false);
        setEditingAgentItem(null);
        setUserFormNotification(`AI Agent '${editAgentName}' updated successfully!`);
        const agents = await ApiService.getAIAgents();
        if (agents.success) setAiAgentsList(agents.data);
      } else {
        alert(`Failed to update agent: ${res.error}`);
      }
    } catch (err: any) {
      alert(`Error updating agent: ${err.message}`);
    }
  };

