  // Intelligent Prompt Name generation based on full system instructions & category analysis
  const generateSmartPromptName = (category: string, customCategory: string, text: string): string => {
    const catLabel = customCategory?.trim() || (category !== 'CUSTOM' ? `${category.charAt(0) + category.slice(1).toLowerCase()} Prompt` : 'Custom Prompt');
    
    // Category default descriptions if instructions haven't been typed yet
    const categoryDefaults: Record<string, string> = {
      SYSTEM: 'Global Platform System Persona & Guardrails',
      QUERY: 'Customer Support Inquiry & Retrieval Handler',
      KYC: 'Identity & Document Verification Handler',
      PAYMENT: 'Payment Settlement & Billing Dispute Handler',
      CALLING: 'Voice Telephony & Real-Time Call Guide',
      EMAIL: 'Customer Email Support & Ticketing Handler',
      WHATSAPP: 'Conversational Messaging & Quick Response Guide',
      ESCALATION: 'High-Priority Human Escalation Handler',
      TRANSLATION: 'Multilingual Neural Translation Engine',
      ORCHESTRATOR: 'Master Intent Router & Task Dispatcher',
      EVALUATION: 'Conversation Quality & Sentiment Evaluation'
    };

    if (!text || text.trim().length < 3) {
      if (categoryDefaults[category]) {
        return `${catLabel}: ${categoryDefaults[category]}`;
      }
      return `${catLabel}: Custom Platform Instructions`;
    }

    const cleanText = text.replace(/\{\{[^}]+\}\}/g, '').trim();
    const lower = cleanText.toLowerCase();

    // 1. Analyze semantic intent & purpose from instructions
    let purpose = '';

    if (lower.includes('kyc') || lower.includes('document') || lower.includes('passport') || lower.includes('aadhaar') || lower.includes('id proof') || lower.includes('identity') || lower.includes('verification')) {
      if (lower.includes('ocr') || lower.includes('extract')) purpose = 'Document OCR & Identity Extraction';
      else if (lower.includes('reject') || lower.includes('fail') || lower.includes('invalid')) purpose = 'KYC Rejection & Resubmission Handler';
      else if (lower.includes('fraud') || lower.includes('tamper') || lower.includes('fake')) purpose = 'KYC Fraud & Document Tamper Check';
      else if (lower.includes('address') || lower.includes('utility')) purpose = 'Address Proof Verification';
      else purpose = 'Identity & KYC Document Validation';
    } else if (lower.includes('refund') || lower.includes('chargeback') || lower.includes('dispute') || lower.includes('reversal')) {
      purpose = 'Refund & Payment Dispute Handler';
    } else if (lower.includes('payment') || lower.includes('invoice') || lower.includes('billing') || lower.includes('checkout') || lower.includes('subscription') || lower.includes('transaction')) {
      if (lower.includes('failed') || lower.includes('retry') || lower.includes('declined')) purpose = 'Failed Payment Recovery & Retry';
      else if (lower.includes('invoice') || lower.includes('receipt')) purpose = 'Invoice & Receipt Generation';
      else purpose = 'Billing & Payment Settlement Handler';
    } else if (lower.includes('escalat') || lower.includes('supervisor') || lower.includes('human agent') || lower.includes('priority') || lower.includes('tier 2') || lower.includes('tier 3')) {
      purpose = 'High-Priority Human Escalation Handler';
    } else if (lower.includes('guardrail') || lower.includes('security') || lower.includes('safety') || lower.includes('jailbreak') || lower.includes('sanitize') || lower.includes('system prompt')) {
      purpose = 'Platform System Persona & Guardrails';
    } else if (lower.includes('translat') || lower.includes('language') || lower.includes('multilingual') || lower.includes('tamil') || lower.includes('hindi') || lower.includes('spanish')) {
      purpose = 'Multilingual Neural Translation Engine';
    } else if (lower.includes('order') || lower.includes('track') || lower.includes('shipping') || lower.includes('delivery') || lower.includes('dispatch') || lower.includes('courier')) {
      purpose = 'Order Tracking & Shipment Dispatch Guide';
    } else if (lower.includes('password') || lower.includes('reset') || lower.includes('login') || lower.includes('2fa') || lower.includes('otp') || lower.includes('auth')) {
      purpose = 'Account Access & Security Reset Handler';
    } else if (lower.includes('whatsapp') || lower.includes('sms') || lower.includes('chat') || lower.includes('messaging')) {
      purpose = 'Conversational Messaging & Quick Response';
    } else if (lower.includes('call') || lower.includes('voice') || lower.includes('telephony') || lower.includes('speech') || lower.includes('ivr')) {
      purpose = 'Voice Telephony & Real-Time Call Guide';
    } else if (lower.includes('email') || lower.includes('ticket') || lower.includes('newsletter') || lower.includes('subject')) {
      purpose = 'Customer Email Response & Ticketing';
    } else if (lower.includes('sentiment') || lower.includes('evaluat') || lower.includes('score') || lower.includes('quality') || lower.includes('audit') || lower.includes('csat')) {
      purpose = 'Conversation Quality & Sentiment Evaluation';
    } else if (lower.includes('orchestrat') || lower.includes('router') || lower.includes('intent') || lower.includes('dispatch') || lower.includes('classify')) {
      purpose = 'Intent Classification & Dynamic Routing';
    } else if (lower.includes('vip') || lower.includes('churn') || lower.includes('retention') || lower.includes('profile') || lower.includes('loyalty')) {
      purpose = 'VIP Customer Synthesis & Retention Handler';
    } else if (lower.includes('faq') || lower.includes('knowledge') || lower.includes('rag') || lower.includes('search') || lower.includes('retriev')) {
      purpose = 'Knowledge Retrieval & FAQ Specialist';
    }

    // 2. Fallback: Parse core action or role from instructions
    if (!purpose) {
      const roleMatch = cleanText.match(/(?:you are (?:an?|the)?|act as (?:an?|the)?|your role is to|help (?:the)? customer (?:with|to)?)\s+([a-zA-Z0-9\s,-]{4,40}?)(?:\.|\n|;|\||, and)/i);
      if (roleMatch && roleMatch[1]) {
        const extracted = roleMatch[1].trim().replace(/\s+/g, ' ');
        purpose = extracted.replace(/\b\w/g, c => c.toUpperCase());
      } else {
        const firstLine = cleanText.split(/[\n\.]/)[0] || '';
        const words = firstLine.trim().split(/\s+/).slice(0, 5).join(' ');
        const cleaned = words.replace(/[^a-zA-Z0-9\s]/g, '').trim();
        if (cleaned.length > 3) {
          purpose = cleaned.replace(/\b\w/g, c => c.toUpperCase());
        } else if (categoryDefaults[category]) {
          purpose = categoryDefaults[category];
        } else {
          purpose = 'Custom Handler';
        }
      }
    }

    // Format final standard prompt name
    return `${catLabel}: ${purpose}`;
  };

